  }
  static float F(uint w){return BitConverter.ToSingle(BitConverter.GetBytes(w),0);}
static uint AbsSign(uint w){return w&0x7fffffff;}static uint ConditionalAbs(uint w){return F(w)<0?w^0x80000000:w;}public static void Update(SoundSetupImage m,uint record,uint emitter){unchecked{uint[] matrix=new uint[16];for(uint i=0;i<16;i++)matrix[i]=m.Word(emitter+0x40+i*4);for(uint i=0;i<3;i++)matrix[12+i]=N.Add(N.Word(matrix[12+i]),N.Word(m.Word(emitter+0x190+i*4))).Store();N drift=N.Add(N.Word(m.Word(record+0x20)),N.Word(m.Word(record+0x1c)));uint[] extents=new uint[3];extents[0]=N.Add(N.Add(N.Mul(N.Word(m.Word(record+0x4c)),N.Word(m.Word(record+0xa4))),N.Mul(N.Word(AbsSign(m.Word(record+0x64))),drift)),N.Word(m.Word(record+0x58))).Store();extents[1]=N.Add(N.Add(N.Mul(N.Add(N.Word(m.Word(record+0x50)),N.Word(AbsSign(m.Word(record+0x48)))),N.Word(m.Word(record+0xa4))),N.Mul(N.Word(AbsSign(m.Word(record+0x68))),drift)),N.Word(m.Word(record+0x5c))).Store();extents[2]=N.Add(N.Add(N.Mul(N.Word(m.Word(record+0x54)),N.Word(m.Word(record+0xa4))),N.Mul(N.Word(AbsSign(m.Word(record+0x6c))),drift)),N.Word(m.Word(record+0x60))).Store();uint[] output=new uint[3];for(uint i=0;i<3;i++)output[i]=N.Add(N.Add(N.Mul(N.Word(extents[0]),N.Word(m.Word(emitter+0x80+i*4))),N.Mul(N.Word(extents[1]),N.Word(m.Word(emitter+0x90+i*4)))),N.Mul(N.Word(extents[2]),N.Word(m.Word(emitter+0xa0+i*4)))).Store();uint padding=N.Mul(N.Word(m.Word(record+0x14c)),N.Word(0x38d1b717)).Store();for(int i=0;i<3;i++){uint absolute=ConditionalAbs(output[i]);uint expanded=N.Add(N.Word(absolute),N.Word(padding)).Store();output[i]=N.Add(N.Word(expanded),N.Word(0x3e4ccccd)).Store();}uint[] minimum=new uint[]{output[0]^0x80000000,output[1]^0x80000000,output[2]^0x80000000};uint acceleration=m.Word(record+0xa0);if(F(acceleration)>0){N product=N.Mul(N.Mul(N.Word(m.Word(record+0xa4)),N.Word(acceleration)),N.Word(m.Word(record+0xa4)));output[1]=N.Add(product,N.Word(output[1])).Store();}else if(F(acceleration)<0){N product=N.Mul(N.Mul(N.Word(m.Word(record+0xa4)),N.Word(acceleration)),N.Word(m.Word(record+0xa4)));minimum[1]=N.Add(product,N.Word(minimum[1])).Store();}uint xz=F(output[2])<F(output[0])?output[0]:output[2],negativeY=minimum[1]^0x80000000,y=F(negativeY)<F(output[1])?output[1]:negativeY;uint radius;if(F(xz)<=F(y))radius=F(output[1])<=F(negativeY)?negativeY:output[1];else radius=F(output[2])<F(output[0])?output[0]:output[2];m.Word(emitter+0x300,radius);m.Word(emitter+0x304,minimum[0]);m.Word(emitter+0x308,minimum[1]);m.Word(emitter+0x310,output[0]);m.Word(emitter+0x30c,minimum[2]);m.Word(emitter+0x314,output[1]);m.Word(emitter+0x318,output[2]);for(uint i=0;i<16;i++)m.Word(emitter+i*4,matrix[i]);}}}}
